        const helpId = question.helpText ? `${question.id}-help` : "";
        const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${question.legend}</legend>
              ${
                question.helpText
                  ? `<p id="${helpId}" class="help-text">${question.helpText}</p>`
                  : ""
              }
