                    return `
                      <div class="choice">
                        <input id="${choiceId}" name="${question.id}" type="checkbox" value="${choice}">
                        <label for="${choiceId}">${choice}</label>
                      </div>
                    `;
                  })
                  .join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

