   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>
     <script>
       const quizQuestions = [
         {
           id: "question-1",
           legend: "1. Which of these are programming languages commonly used for web development?",
           helpText: "Select every option that is a programming language developers often use when building web applications.",
           choices: ["JavaScript", "TypeScript", "PHP", "Ruby"],
         },
         {
           id: "question-2",
           legend: "2. Which languages are commonly considered statically typed?",
           choices: ["TypeScript", "Java", "Ruby", "C#"],
         },
         {
           id: "question-3",
           legend: "3. Which of these languages are often used for systems programming?",
           choices: ["Rust", "Go", "Swift", "C"],
         },
       ];

       function QuestionField(question) {
         const helpId = question.helpText ? `${question.id}-help` : "";
         const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${question.legend}</legend>
               ${
                 question.helpText
                   ? `<p id="${helpId}" class="help-text">${question.helpText}</p>`
                   : ""
               }
               <div class="choice-grid">
                 ${question.choices
                   .map((choice, index) => {
                     const choiceId = `${question.id}-choice-${index + 1}`;
                     return `
                       <div class="choice">
                         <input id="${choiceId}" name="${question.id}" type="checkbox" value="${choice}">
                         <label for="${choiceId}">${choice}</label>
                       </div>
                     `;
                   })
                   .join("")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizForm() {
         return `
           <form id="quiz-form">
             ${quizQuestions.map((question) => QuestionField(question)).join("")}
             <div class="actions">
               <button type="submit">Show selections</button>
               <p id="quiz-results" class="results" role="status" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       function App() {
         return `
           <main id="maincontent" class="page-shell" tabindex="-1">
             <section class="hero" aria-labelledby="page-title">
               <p class="eyebrow">Interactive quiz</p>
               <h1 id="page-title">Computer languages quiz</h1>
               <p class="intro">
                 Explore language families and use cases. Each question supports multiple answers, so choose every option you think fits.
               </p>
             </section>
             <section class="quiz-card" aria-labelledby="quiz-section-title">
               <h2 id="quiz-section-title">Pick your answers</h2>
               ${QuizForm()}
             </section>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = App();

       const quizForm = document.getElementById("quiz-form");
       const results = document.getElementById("quiz-results");

       quizForm.addEventListener("submit", (event) => {
         event.preventDefault();

         const summary = quizQuestions
           .map((question) => {
             const selected = Array.from(
               quizForm.querySelectorAll(`input[name="${question.id}"]:checked`)
             ).map((input) => input.value);

             return selected.length
               ? `${question.legend.replace(/^\d+\.\s*/, "")}: ${selected.join(", ")}`
               : `${question.legend.replace(/^\d+\.\s*/, "")}: no selections yet`;
           })
           .join(" | ");

         results.textContent = summary;
       });
     </script>
   </body>
 </html>

